static const char kk_mesh_expand_shader[] = "struct KKMeshExpand {\n   kk_mesh_params mesh;\n   ulong root, samplers, per_draw, linked_vs, linked_fs, guard;\n   ulong parameters, grids, range;\n   uint limit, capacity, local[3];\n};\nstruct ICB { command_buffer commands; };\nstatic_assert(sizeof(KKMeshExpand) == KK_MESH_EXPAND_SIZE, \"Mesh expansion ABI\");\nkernel void kk_mesh_expand_commands(constant KKMeshExpand &s [[buffer(KK_ARGUMENT_ROOT)]],\n   constant ICB &icb [[buffer(KK_ARGUMENT_SAMPLERS)]])\n{\n   device kk_mesh_batch *batch = (device kk_mesh_batch *)s.mesh.batch;\n   device kk_mesh_task_record *record = (device kk_mesh_task_record *)s.mesh.records;\n   uint total = 0;\n   for (uint i = 0; i < batch->task_count; ++i) {\n      total += record[i].grid[0] * record[i].grid[1] * record[i].grid[2];\n      record[i].prefix_end = total;\n   }\n   batch->mesh_count = total;\n   uint needed = total / s.limit + uint(total % s.limit != 0);\n   device uint *range = (device uint *)s.range;\n   range[0] = 0; range[1] = needed;\n   for (uint i = 0; i < needed; ++i) {\n      uint base = i * s.limit, groups = min(total - base, s.limit);\n      uint width = min(groups, 65535u);\n      uint height = (groups + width - 1u) / width;\n      if (ulong(width) * height > 2097152ul) {\n         width = min(groups, 32768u);\n         height = (groups + width - 1u) / width;\n      }\n      uint3 grid(width, height, 1);\n      device kk_mesh_params *params = (device kk_mesh_params *)s.parameters + i;\n      *params = s.mesh; params->pad = base;\n      device uint *args = (device uint *)s.grids + i * 3;\n      args[0] = grid.x; args[1] = grid.y; args[2] = grid.z;\n      render_command cmd(icb.commands, i);\n      cmd.reset();\n      cmd.set_object_buffer((device void *)s.root, KK_ARGUMENT_ROOT);\n      cmd.set_mesh_buffer((device void *)s.root, KK_ARGUMENT_ROOT);\n      cmd.set_fragment_buffer((device void *)s.root, KK_ARGUMENT_ROOT);\n      cmd.set_object_buffer((device void *)s.samplers, KK_ARGUMENT_SAMPLERS);\n      cmd.set_mesh_buffer((device void *)s.samplers, KK_ARGUMENT_SAMPLERS);\n      cmd.set_fragment_buffer((device void *)s.samplers, KK_ARGUMENT_SAMPLERS);\n      cmd.set_object_buffer((device void *)s.per_draw, KK_ARGUMENT_PER_DRAW);\n      cmd.set_mesh_buffer((device void *)s.per_draw, KK_ARGUMENT_PER_DRAW);\n      cmd.set_fragment_buffer((device void *)s.per_draw, KK_ARGUMENT_PER_DRAW);\n      cmd.set_object_buffer(params, KK_ARGUMENT_MESH_PARAMETERS);\n      cmd.set_mesh_buffer(params, KK_ARGUMENT_MESH_PARAMETERS);\n      cmd.set_fragment_buffer(params, KK_ARGUMENT_MESH_PARAMETERS);\n      cmd.set_object_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY);\n      cmd.set_mesh_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY);\n      cmd.set_fragment_buffer((device void *)0, KK_ARGUMENT_POLY_LAYER_REPLAY);\n      if (s.linked_vs) {\n         cmd.set_object_buffer((device void *)s.linked_vs, KK_ARGUMENT_VS_VFT_WRAPPER);\n         cmd.set_mesh_buffer((device void *)s.linked_vs, KK_ARGUMENT_VS_VFT_WRAPPER);\n      }\n      if (s.linked_fs) cmd.set_fragment_buffer((device void *)s.linked_fs, KK_ARGUMENT_FS_VFT_WRAPPER);\n      if (s.guard) cmd.set_fragment_buffer((device void *)s.guard, KK_ARGUMENT_INTERLOCK_GUARD);\n      cmd.draw_mesh_threadgroups(grid, uint3(1), uint3(s.local[0], s.local[1], s.local[2]));\n   }\n}\n";
